import {useEffect,useState} from 'react';
import {Brand,Field,Form} from './ui';
import {api} from './api';
import {ArrowUpRight,Eye,EyeOff,Moon,Sun} from 'lucide-react';
import './network-intro.css';
import ThemeToggle from './ThemeToggle';

export default function Auth({onLogin,role}) {
 const [forgot,setForgot]=useState(false),[resetSent,setResetSent]=useState(false),[resetReady,setResetReady]=useState(false);
 const [emailMode,setEmailMode]=useState(false),[emailReady,setEmailReady]=useState(false),[email,setEmail]=useState(''),[mfaRequired,setMfaRequired]=useState(false);
 const [register,setRegister]=useState(false),[codeSent,setCodeSent]=useState(false),[registration,setRegistration]=useState(null),[showPassword,setShowPassword]=useState(false),[notice,setNotice]=useState('');
 useEffect(()=>{api('/auth/options').then(v=>{setEmailReady(v.registrationEmail);setResetReady(Boolean(v.passwordReset));}).catch(()=>{});},[]);
 const finishRegistration=async(data)=>{await api('/auth/register','POST',{...registration,emailCode:data.emailCode});await api('/auth/login','POST',{email:registration.email,password:registration.password});await onLogin();};
 return <main className="auth-layout"><section className="auth-story"><Brand/><div className="auth-story-content"><h1>One network.<br/><span>Every journey.</span></h1><p>Shop, manage your business and deliver.<br/>One shared DEN account.</p></div><footer><span>DEN Global Network</span><ArrowUpRight size={18}/></footer></section><section className="auth-form"><div className="auth-inner"><div className="auth-heading-row"><p className="muted">DEN Global</p><ThemeToggle className="auth-theme-toggle"/></div><h2>{forgot?'Reset your password.':register?(codeSent?'Verify your email.':'Join the network.'):'Welcome back.'}</h2><p className="muted">{forgot?'Recover access to your DEN account.':register?(codeSent?`If this address can be registered, enter the 6-digit code emailed to ${registration?.email}.`:'Create your account and start in Consumer.'):'Sign in to continue your DEN journey.'}</p>{notice?<p role="status" className="notice">{notice}</p>:null}{!forgot&&!register&&emailReady?<button className="text-button" onClick={()=>{setMfaRequired(false);setEmailMode(!emailMode);}}>{emailMode?'Use password instead':'Sign in with an email code'}</button>:null}
 {forgot?<><Form key={resetSent?'reset-confirm':'reset-request'} submit={resetSent?'Reset password':'Send reset code'} submitDisabled={!resetReady} onSubmit={async data=>{if(resetSent){await api('/auth/reset-password','POST',data);setForgot(false);setResetSent(false);setNotice('Your password has been reset. Sign in with your new password.');}else{await api('/auth/forgot-password','POST',{email:data.email});setEmail(data.email);setResetSent(true);}}}><Field label="Email address" name="email" type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/>{resetSent?<><Field label="Reset code" name="code" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code"/><Field label="New password" name="password" type="password" required minLength={12} maxLength={128} pattern="(?=.*[A-Za-z])(?=.*[0-9]).{12,128}" autoComplete="new-password"/><p className="small muted">Use at least 12 characters, including a letter and a number. The code expires in 10 minutes. Resetting your password signs out existing sessions; two-step verification stays enabled.</p></>:null}<p className="small muted" role="status">{!resetReady?'Password-reset emails are not available yet. Please try again once email delivery is enabled.':resetSent?'If this address belongs to an active account, a reset code has been emailed. Check your inbox and spam folder.':'We will email a one-time code if this address belongs to an active account.'}</p></Form><button type="button" className="text-button" onClick={()=>{setForgot(false);setResetSent(false);setNotice('');}}>Back to sign in</button></>:register&&codeSent?<><Form key="registration-code" submit="Verify email and create account" onSubmit={finishRegistration}><Field label="Email verification code" name="emailCode" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code"/><p className="small muted">The code expires in 10 minutes. Check your spam folder if it does not arrive.</p></Form><button className="text-button" onClick={()=>{setCodeSent(false);setNotice('');setMfaRequired(false);}}>Change details or resend code</button></>:<Form key={`${register}-${emailMode}`} submit={register?'Send verification code':'Sign in'} submitDisabled={register&&!emailReady} onSubmit={async data=>{
  if(register){const result=await api('/auth/register-code','POST',data);setRegistration(data);setEmail(data.email);setCodeSent(true);setNotice(result.message);return;}
  try{await api('/auth/login','POST',data);await onLogin();}catch(error){if(error.code==='MFA_CODE_REQUIRED_OR_REUSED'){setMfaRequired(true);setNotice('Enter the current code from your authenticator app to finish signing in.');return;}throw error;}
 }}>
 {register?<><Field label="Full name" name="name" required autoComplete="name" maxLength={100}/><Field label="Phone number" name="phone" type="tel" required autoComplete="tel" maxLength={40}/><Field label="Country"><select name="country" required><option value="NG">Nigeria</option><option value="GB">United Kingdom</option><option value="US">United States</option><option value="MA">Morocco</option></select></Field></>:null}
 <Field label="Email address" type="email" name="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)}/>
 {!register&&(mfaRequired||emailMode)?<Field label="Authenticator code" name="code" required pattern="[0-9]{6}" maxLength={6} inputMode="numeric" autoComplete="one-time-code"/>:null}
 {!emailMode||register?<Field label="Password"><span className="password-control"><input name="password" type={showPassword?'text':'password'} required minLength={register?12:1} maxLength={128} pattern={register?'(?=.*[A-Za-z])(?=.*[0-9]).{12,128}':undefined} title={register?'Use at least 12 characters, including a letter and a number.':undefined} autoComplete={register?'new-password':'current-password'}/><button type="button" className="password-toggle" aria-label={showPassword?'Hide password':'Show password'} aria-pressed={showPassword} onClick={()=>setShowPassword(!showPassword)}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></span></Field>:<><p className="small muted">For accounts with two-step authentication enabled. Keep your authenticator code ready.</p><button type="button" className="secondary" onClick={async()=>{try{const v=await api('/auth/email-code','POST',{email});setNotice(v.message);}catch(e){setNotice(e.message);}}}>Send sign-in email</button><Field label="Email sign-in code" name="emailCode" required inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code"/></>}
 {register?<p className="small muted">Use at least 12 characters, including at least one letter and one number. {emailReady?'We’ll email you a one-time code to verify your address.':'Email verification is temporarily unavailable, so account creation is paused.'} Registration does not approve your business or activate live shipments.</p>:null}
 </Form>}
 {!forgot&&!register?<button type="button" className="text-button forgot-password" onClick={()=>{setForgot(true);setNotice('');}}>Forgot password?</button>:null}{!forgot?<p className="auth-switch">{register?'Already part of DEN?':'New to the network?'} <button className="text-button" onClick={()=>{setRegister(!register);setEmailMode(false);setCodeSent(false);setRegistration(null);setNotice('');setMfaRequired(false);}}>{register?'Sign in':'Create an account'}</button></p>:null}<p className="small muted">International Trade is locked by default. No payment collection is enabled.</p></div></section></main>;
}
